    "text_blocks": [
      {
        "type": "paragraph",
        "snippet": "You can link your Aadhaar with your PAN card online through the Income Tax e-Filing Portal by paying a late fee and submitting your details.",
        "snippet_links": [
          {
            "text": "Income Tax e-Filing Portal",
            "link": "https://www.incometax.gov.in/iec/foportal"
          }
        ],
        "snippet_highlighted_words": [
          "through the Income Tax e-Filing Portal by paying a late fee and submitting your details"
        ],
        "reference_indexes": [
          0,
          1
        ]
      },
      {
        "type": "heading",
        "snippet": "Step 1: Pay the Fee (e-Pay Tax)"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Go to the Income Tax e-Filing Portal and click Link Aadhaar under the Quick Links section.",
            "reference_indexes": [
              0
            ]
          },
          {
            "snippet": "Enter your PAN and Aadhaar Number, then click Continue to Pay Through e-Pay Tax.",
            "reference_indexes": [
              0
            ]
          },
          {
            "snippet": "Enter your mobile number to get an OTP, verify it, and log into the tax payment page.",
            "reference_indexes": [
              0
            ]
          },
          {
            "snippet": "Select the correct Assessment Year and choose Other Receipts (500) as the type of payment.",
            "reference_indexes": [
              0
            ]
          },
          {
            "snippet": "Complete the applicable late fee payment (currently ₹1,000) through your preferred net banking or debit card mode.",
            "reference_indexes": [
              2,
              3
            ]
          }
        ]
      },
      {
        "type": "heading",
        "snippet": "Step 2: Submit the Link Request"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Once the payment is successful, return to the Link Aadhaar section on the home page.",
            "reference_indexes": [
              0
            ]
          },
          {
            "snippet": "Re-enter your PAN and Aadhaar Number and click Validate.",
            "reference_indexes": [
              4
            ]
          },
          {
            "snippet": "Enter your name as per your Aadhaar card and your mobile number.",
            "reference_indexes": [
              4
            ]
          },
          {
            "snippet": "Enter the OTP received on your mobile number and submit the request.",
            "reference_indexes": [
              2
            ]
          }
        ]
      },
      {
        "type": "paragraph",
        "snippet": "Note: The linking request usually takes a few working days to process and reflect in the system.",
        "reference_indexes": [
          1
        ]
      }
    ],
